public class Main {
    public static void main(String[] args) {
        // 첫 인자는 메모, 둘째 인자는 주문 코드예요.
        System.out.println("인자 수: " + args.length);
        System.out.println("메모: " + args[0]);
        System.out.println("코드: " + args[1]);
    }
}

